import{_ as a,o as l,c as r,a2 as e}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"《AI Agent 实战》第六章：Agent 的评估 - 知识笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/06-chapter6.md","filePath":"study/ai-agent-book/06-chapter6.md","lastUpdated":1785465991000}'),i={name:"study/ai-agent-book/06-chapter6.md"};function o(d,t,n,s,h,g){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="《ai-agent-实战》第六章-agent-的评估-知识笔记" tabindex="-1">《AI Agent 实战》第六章：Agent 的评估 - 知识笔记 <a class="header-anchor" href="#《ai-agent-实战》第六章-agent-的评估-知识笔记" aria-label="Permalink to &quot;《AI Agent 实战》第六章：Agent 的评估 - 知识笔记&quot;">​</a></h1><hr><h2 id="一、核心概念" tabindex="-1">一、核心概念 <a class="header-anchor" href="#一、核心概念" aria-label="Permalink to &quot;一、核心概念&quot;">​</a></h2><h3 id="_1-评估体系的核心定位" tabindex="-1">1. 评估体系的核心定位 <a class="header-anchor" href="#_1-评估体系的核心定位" aria-label="Permalink to &quot;1. 评估体系的核心定位&quot;">​</a></h3><ul><li><strong>评估对象</strong>：不应只是模型，而是<strong>模型与 Harness 的组合体</strong></li><li><strong>评估价值</strong>：为设计决策提供科学依据，区分真正的能力提升与表面波动</li><li><strong>核心功能</strong>：在 Harness 中扮演&quot;验证&quot;功能的核心角色</li></ul><h3 id="_2-评估体系的三个层次" tabindex="-1">2. 评估体系的三个层次 <a class="header-anchor" href="#_2-评估体系的三个层次" aria-label="Permalink to &quot;2. 评估体系的三个层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>核心问题</th><th>内容</th></tr></thead><tbody><tr><td>第一层：评估环境</td><td>在哪里测</td><td>搭建自动化、可复现的测试环境</td></tr><tr><td>第二层：评估方法</td><td>怎么判</td><td>数据集设计、指标体系、LLM-as-a-Judge</td></tr><tr><td>第三层：评估驱动的决策</td><td>测了干什么</td><td>模型选型、架构优化、持续迭代</td></tr></tbody></table><h3 id="_3-评估环境的五种要素" tabindex="-1">3. 评估环境的五种要素 <a class="header-anchor" href="#_3-评估环境的五种要素" aria-label="Permalink to &quot;3. 评估环境的五种要素&quot;">​</a></h3><ol><li><strong>数据集（Dataset）</strong>：任务集合，含初始状态、目标描述、参考方案</li><li><strong>环境状态（Environment State）</strong>：任务执行中的可变信息</li><li><strong>工具接口（Tools）</strong>：Agent 可执行的操作集合</li><li><strong>评分标准（Rubric）</strong>：量化 Agent 表现的准则</li><li><strong>执行协议（Interaction Protocol）</strong>：交互模式和终止条件</li></ol><h3 id="_4-两种核心评估范式" tabindex="-1">4. 两种核心评估范式 <a class="header-anchor" href="#_4-两种核心评估范式" aria-label="Permalink to &quot;4. 两种核心评估范式&quot;">​</a></h3><h4 id="工具调用型评估环境" tabindex="-1">工具调用型评估环境 <a class="header-anchor" href="#工具调用型评估环境" aria-label="Permalink to &quot;工具调用型评估环境&quot;">​</a></h4><ul><li><strong>Verifiers 框架层次化设计</strong>： <ul><li><code>SingleTurnEnv</code>：单轮任务（无状态、无工具）</li><li><code>ToolEnv</code>：多轮工具调用（无状态、多轮）</li><li><code>StatefulToolEnv</code>：有状态工具调用（有状态、多轮）</li><li><code>SandboxEnv</code>：沙盒环境（有状态+隔离、多轮）</li></ul></li><li><strong>验证方式</strong>：基于可执行标准（测试通过、答案匹配）</li></ul><h4 id="人机交互型评估环境" tabindex="-1">人机交互型评估环境 <a class="header-anchor" href="#人机交互型评估环境" aria-label="Permalink to &quot;人机交互型评估环境&quot;">​</a></h4><ul><li><strong>核心理念</strong>：渐进式信息透露（Progressive Information Disclosure）</li><li><strong>τ-bench 方案</strong>：用户模拟（User Simulation）——用另一个 LLM 扮演用户</li><li><strong>τ²-bench 增量</strong>： <ul><li>双控环境：用户模拟器也能操作共享环境</li><li>更精确的任务规范与组合式任务生成</li></ul></li></ul><h3 id="_5-关键评估指标" tabindex="-1">5. 关键评估指标 <a class="header-anchor" href="#_5-关键评估指标" aria-label="Permalink to &quot;5. 关键评估指标&quot;">​</a></h3><h4 id="pass-k-vs-pass-k-vs-best-k" tabindex="-1">Pass@k vs Pass^k vs Best@k <a class="header-anchor" href="#pass-k-vs-pass-k-vs-best-k" aria-label="Permalink to &quot;Pass@k vs Pass^k vs Best@k&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>定义</th><th>适用场景</th></tr></thead><tbody><tr><td>Pass@k</td><td>k 次尝试中至少有一次成功</td><td>评估能力天花板（探索性任务）</td></tr><tr><td>Pass^k</td><td>k 次尝试全部成功</td><td>验证稳定性（回归测试）</td></tr><tr><td>Best@k</td><td>k 次尝试中最好的得分</td><td>开放任务的质量上限</td></tr></tbody></table><h3 id="_6-llm-as-a-judge" tabindex="-1">6. LLM-as-a-Judge <a class="header-anchor" href="#_6-llm-as-a-judge" aria-label="Permalink to &quot;6. LLM-as-a-Judge&quot;">​</a></h3><ul><li><strong>定义</strong>：让语言模型根据专家定义的评分标准（Rubric）进行评判</li><li><strong>价值</strong>：在自动化规模和人类专业判断之间取得平衡</li><li><strong>已知局限</strong>： <ul><li>长度偏差（倾向给更长的回答打高分）</li><li>同源模型问题（Agent 可能学会利用评判模型偏好）</li></ul></li></ul><hr><h2 id="二、关键观点" tabindex="-1">二、关键观点 <a class="header-anchor" href="#二、关键观点" aria-label="Permalink to &quot;二、关键观点&quot;">​</a></h2><h3 id="_1-评估的首要价值" tabindex="-1">1. 评估的首要价值 <a class="header-anchor" href="#_1-评估的首要价值" aria-label="Permalink to &quot;1. 评估的首要价值&quot;">​</a></h3><blockquote><p><strong>评估体系的首要价值不是给当前系统打分，而是让你能快速、可靠地跟上模型的演进。</strong></p></blockquote><p>拥有完善评估体系的团队，当新模型发布时能在数小时内得出切换决策；缺乏评估体系的团队只能凭直觉或等待社区反馈。</p><h3 id="_2-模型替换实验-vs-消融实验" tabindex="-1">2. 模型替换实验 vs 消融实验 <a class="header-anchor" href="#_2-模型替换实验-vs-消融实验" aria-label="Permalink to &quot;2. 模型替换实验 vs 消融实验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>操作</th><th>目的</th></tr></thead><tbody><tr><td>模型替换实验</td><td>固定 Harness，只换模型</td><td>区分瓶颈在模型还是 Harness</td></tr><tr><td>消融实验</td><td>关闭 Harness 某个组件</td><td>定位 Harness 内部哪个部件重要</td></tr></tbody></table><h3 id="_3-数据集设计的五大挑战" tabindex="-1">3. 数据集设计的五大挑战 <a class="header-anchor" href="#_3-数据集设计的五大挑战" aria-label="Permalink to &quot;3. 数据集设计的五大挑战&quot;">​</a></h3><ol><li><strong>明确性与开放性的张力</strong></li><li><strong>真实性与可控性的平衡</strong></li><li><strong>多样性与系统性的协调</strong></li><li><strong>评估成本与覆盖范围</strong></li><li><strong>数据泄漏防范</strong></li></ol><h3 id="_4-数据泄漏防范策略" tabindex="-1">4. 数据泄漏防范策略 <a class="header-anchor" href="#_4-数据泄漏防范策略" aria-label="Permalink to &quot;4. 数据泄漏防范策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基准</th><th>防范策略</th></tr></thead><tbody><tr><td>GAIA</td><td>答案独特性 + 专门创建的附件文件</td></tr><tr><td>SWE-bench-Live</td><td>时间新鲜度（收录训练截止日期后的新 issue）</td></tr><tr><td>τ²-bench</td><td>动态参数生成（每次随机生成具体实例）</td></tr><tr><td>AndroidWorld</td><td>参数化任务生成 + 基于 UI 状态验证</td></tr><tr><td>Terminal-Bench</td><td>金丝雀标识符（canary GUID）使泄漏可检测</td></tr></tbody></table><h3 id="_5-rubric-四准则-scale-ai" tabindex="-1">5. Rubric 四准则（Scale AI） <a class="header-anchor" href="#_5-rubric-四准则-scale-ai" aria-label="Permalink to &quot;5. Rubric 四准则（Scale AI）&quot;">​</a></h3><ol><li><strong>基于专家指导</strong>：必须反映领域知识，捕捉核心事实和推理步骤</li><li><strong>全面覆盖</strong>：涵盖准确性、逻辑性、完整性、安全性，明确陷阱（Pitfall）</li><li><strong>标准重要性权重</strong>：必要项、重要项、可选项、陷阱项；支持<strong>一票否决机制</strong></li><li><strong>自包含评估</strong>：每个评价项独立可操作，不依赖评价者的领域知识</li></ol><h3 id="_6-成本的三个层次" tabindex="-1">6. 成本的三个层次 <a class="header-anchor" href="#_6-成本的三个层次" aria-label="Permalink to &quot;6. 成本的三个层次&quot;">​</a></h3><ol><li><strong>模型推理成本</strong>：输入/输出 token + 上下文累积效应 + 思考 token</li><li><strong>工具调用成本</strong>：外部 API 费用 + 工具返回结果的 token 费用</li><li><strong>基础设施成本</strong>：向量数据库、消息队列、日志存储等</li></ol><h3 id="_7-成本优化三大杠杆" tabindex="-1">7. 成本优化三大杠杆 <a class="header-anchor" href="#_7-成本优化三大杠杆" aria-label="Permalink to &quot;7. 成本优化三大杠杆&quot;">​</a></h3><ul><li><strong>KV Cache 复用</strong>：可降低 30%-60% 的输入 token 成本</li><li><strong>上下文压缩</strong>：控制上下文增长速率</li><li><strong>模型分层路由</strong>：简单请求给轻量模型，复杂任务给强力模型</li></ul><hr><h2 id="三、实践要点" tabindex="-1">三、实践要点 <a class="header-anchor" href="#三、实践要点" aria-label="Permalink to &quot;三、实践要点&quot;">​</a></h2><h3 id="_1-benchmark-报告分析流程" tabindex="-1">1. Benchmark 报告分析流程 <a class="header-anchor" href="#_1-benchmark-报告分析流程" aria-label="Permalink to &quot;1. Benchmark 报告分析流程&quot;">​</a></h3><ol><li><strong>诊断</strong>：交叉分析逐任务表格和能力标签矩阵</li><li><strong>构建假设</strong>：按三层框架（表层→中层→深层）</li><li><strong>分阶段实验</strong>：验证假设，观察改进幅度和副作用</li><li><strong>数据驱动决策</strong>：权衡成本收益比</li><li><strong>迭代</strong>：改进后重新评估，新报告成为下一轮起点</li></ol><h3 id="_2-假设分层框架" tabindex="-1">2. 假设分层框架 <a class="header-anchor" href="#_2-假设分层框架" aria-label="Permalink to &quot;2. 假设分层框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>特点</th><th>示例</th></tr></thead><tbody><tr><td>表层假设</td><td>成本低、可并行验证</td><td>增加导航提示、补充 UI 元素识别规则</td></tr><tr><td>中层假设</td><td>同样独立、可并行</td><td>修复多模态输入管道、启用思考模式</td></tr><tr><td>深层假设</td><td>验证成本高，条件化启动</td><td>更换视觉模型、增加 UI 元素树信息</td></tr></tbody></table><h3 id="_3-内部评估基础设施五大组件" tabindex="-1">3. 内部评估基础设施五大组件 <a class="header-anchor" href="#_3-内部评估基础设施五大组件" aria-label="Permalink to &quot;3. 内部评估基础设施五大组件&quot;">​</a></h3><ol><li><strong>消融基础设施</strong>：每个主要特性可独立关闭，定期验证实际贡献</li><li><strong>AB 测试方法论</strong>：多臂设计、区分机制指标和目标指标、设置护栏指标</li><li><strong>双层特性开关系统</strong>：编译时开关 + 运行时开关</li><li><strong>提示词敏感性评估</strong>：可确定性渲染、版本化快照、回归测试</li><li><strong>隐私感知的分析</strong>：类型系统强制隐私约束</li></ol><h3 id="_4-仿真环境设计要点" tabindex="-1">4. 仿真环境设计要点 <a class="header-anchor" href="#_4-仿真环境设计要点" aria-label="Permalink to &quot;4. 仿真环境设计要点&quot;">​</a></h3><ul><li><strong>与评估环境的核心区别</strong>： <ul><li>交互频率远高（数百万次 vs 数千次）</li><li>需要随机化（防止死记硬背）</li><li>必须提供即时反馈</li></ul></li><li><strong>两大要求</strong>： <ul><li>可靠的 reset 语义</li><li>远高于评估的吞吐</li></ul></li><li><strong>领域随机化</strong>：缩小仿真与现实差距（sim-to-real gap）</li></ul><hr><h2 id="四、扩展思考" tabindex="-1">四、扩展思考 <a class="header-anchor" href="#四、扩展思考" aria-label="Permalink to &quot;四、扩展思考&quot;">​</a></h2><h3 id="_1-思考题精选" tabindex="-1">1. 思考题精选 <a class="header-anchor" href="#_1-思考题精选" aria-label="Permalink to &quot;1. 思考题精选&quot;">​</a></h3><h4 id="数据泄漏的-猫鼠游戏-有终局吗" tabindex="-1">数据泄漏的&quot;猫鼠游戏&quot;有终局吗？ <a class="header-anchor" href="#数据泄漏的-猫鼠游戏-有终局吗" aria-label="Permalink to &quot;数据泄漏的&quot;猫鼠游戏&quot;有终局吗？&quot;">​</a></h4><ul><li><strong>现状</strong>：公开 benchmark 数据很快被纳入训练数据</li><li><strong>思考方向</strong>： <ul><li>动态生成机制（参数化模板）</li><li>时间新鲜度策略（持续收录新问题）</li><li>金丝雀标识符使泄漏可追踪</li></ul></li><li><strong>根本矛盾</strong>：评估需要公开，公开则可能泄漏</li></ul><h4 id="llm-as-a-judge-的系统性盲区" tabindex="-1">LLM-as-a-Judge 的系统性盲区 <a class="header-anchor" href="#llm-as-a-judge-的系统性盲区" aria-label="Permalink to &quot;LLM-as-a-Judge 的系统性盲区&quot;">​</a></h4><ul><li><strong>问题</strong>：模型可能给某种风格打高分，与人类判断不一致</li><li><strong>应对</strong>： <ul><li>多源异构评判（使用不同模型家族）</li><li>人工标注金标集校准</li><li>定期审计评分与回答长度的相关性</li></ul></li></ul><h4 id="配对比较中的非传递性偏好" tabindex="-1">配对比较中的非传递性偏好 <a class="header-anchor" href="#配对比较中的非传递性偏好" aria-label="Permalink to &quot;配对比较中的非传递性偏好&quot;">​</a></h4><ul><li><strong>理论假设</strong>：如果 A &gt; B 且 B &gt; C，则 A &gt; C</li><li><strong>现实挑战</strong>：人类偏好经常违反传递性</li><li><strong>影响场景</strong>： <ul><li>不同任务类型间难以排序</li><li>评分依赖具体问题分布</li></ul></li></ul><h3 id="_2-方法论核心" tabindex="-1">2. 方法论核心 <a class="header-anchor" href="#_2-方法论核心" aria-label="Permalink to &quot;2. 方法论核心&quot;">​</a></h3><blockquote><p><strong>观察 → 假设 → 实验 → 验证 → 新认识 → 新假设</strong></p></blockquote><p>这是将 Agent 工程从经验驱动的&quot;炼金术&quot;转向数据驱动的科学工程的关键路径。</p><h3 id="_3-评估闭环" tabindex="-1">3. 评估闭环 <a class="header-anchor" href="#_3-评估闭环" aria-label="Permalink to &quot;3. 评估闭环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>评估环境 → 评估数据集 → 自动化评估方法 → Benchmark 分析 → 系统改进 → 更新评估环境</span></span></code></pre></div><h3 id="_4-与后续章节的联系" tabindex="-1">4. 与后续章节的联系 <a class="header-anchor" href="#_4-与后续章节的联系" aria-label="Permalink to &quot;4. 与后续章节的联系&quot;">​</a></h3><ul><li><strong>第七章</strong>：把评估环境和数据转化为模型后训练的输入</li><li><strong>第八章</strong>：把生产轨迹的多维评价转化为可执行的系统更新</li></ul><hr><h2 id="五、核心基准对比速查" tabindex="-1">五、核心基准对比速查 <a class="header-anchor" href="#五、核心基准对比速查" aria-label="Permalink to &quot;五、核心基准对比速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基准</th><th>类型</th><th>核心特点</th><th>验证方式</th></tr></thead><tbody><tr><td>GAIA</td><td>工具调用型</td><td>三级难度、通用性、附件文件</td><td>字符串精确匹配</td></tr><tr><td>AndroidWorld</td><td>GUI 操作</td><td>116 任务/20 应用、参数化模板</td><td>UI 状态验证</td></tr><tr><td>SWE-Bench Verified</td><td>代码生成</td><td>500 高质量任务、人工验证</td><td>测试通过/FAIL_TO_PASS</td></tr><tr><td>τ²-bench</td><td>人机交互</td><td>渐进式信息透露、双控环境</td><td>数据库状态 + 对话内容</td></tr><tr><td>Terminal-Bench</td><td>终端操作</td><td>200+ 任务、跨技术栈</td><td>文件系统 + 程序执行</td></tr><tr><td>OSWorld</td><td>OS 操作</td><td>跨三个操作系统、134 评估函数</td><td>文件系统 + DOM 树 + 后端验证</td></tr></tbody></table><hr><h2 id="六、行动清单" tabindex="-1">六、行动清单 <a class="header-anchor" href="#六、行动清单" aria-label="Permalink to &quot;六、行动清单&quot;">​</a></h2><h3 id="立即行动" tabindex="-1">立即行动 <a class="header-anchor" href="#立即行动" aria-label="Permalink to &quot;立即行动&quot;">​</a></h3><ol><li>建立可重复运行的评估环境</li><li>设计覆盖典型/边界/陷阱的测试用例</li><li>定义多维度 Rubric，含否决项</li><li>构建评估结果追踪机制</li></ol><h3 id="持续实践" tabindex="-1">持续实践 <a class="header-anchor" href="#持续实践" aria-label="Permalink to &quot;持续实践&quot;">​</a></h3><ol><li>定期运行消融实验，验证每个特性贡献</li><li>建立评估集持续更新机制（从生产轨迹沉淀）</li><li>使用多源评判防范同源模型问题</li><li>在每次提示词变更时运行回归测试</li></ol><h3 id="长期建设" tabindex="-1">长期建设 <a class="header-anchor" href="#长期建设" aria-label="Permalink to &quot;长期建设&quot;">​</a></h3><ol><li>将评估基础设施嵌入产品工程</li><li>构建双层特性开关系统</li><li>建立成本监控与预算控制体系</li><li>培养团队的评估驱动决策文化</li></ol><hr><p><em>本笔记基于《AI Agent 实战》第六章内容整理</em></p>',75)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
